// Intent (Benjamin, 2026-10-11): « prototypes des parcours manquants dans le cockpit actuel ».
// Mechanism: actual cockpit rendering, only the result's detail varies; all state is in memory.
const qp=new URLSearchParams(location.search), variants=['A','B','C'];
const names={A:'Onglets dans le détail',B:'Parcours guidé',C:'Dossier et journal'};
const titles={ready:'Le cockpit attend ton jugement',dossier:'Le dossier du résultat',trial:'Le résultat est ouvert pour ton essai',findings:'Préparer tes constats',returned:'Tes constats ont été rendus',repairing:'L’usine corrige tes constats','new-result':'Un nouveau résultat attend ton jugement',accepted:'Accepté · fusion en attente',merging:'La fusion est en cours',merged:'Le résultat est fusionné',outdated:'Le dossier doit être renouvelé',outage:'Le produit ne démarre pas',conflict:'Un nouveau jugement sera nécessaire',abandoned:'Le chantier est abandonné'};
const screens={ready:'result',dossier:'dossier',trial:'trial',findings:'findings',returned:'follow',repairing:'follow','new-result':'result',accepted:'follow',merging:'follow',merged:'follow',outdated:'dossier',outage:'trial',conflict:'follow',abandoned:'follow'};
const labels={result:'Résultat',dossier:'Dossier',trial:'Essai',findings:'Mes constats',follow:'Suivi'};
let variant=variants.includes(qp.get('variant'))?qp.get('variant'):'A',scene=titles[qp.get('scene')]?qp.get('scene'):'ready';
let screen=qp.get('view')&&labels[qp.get('view')]?qp.get('view'):screens[scene],version=scene==='new-result'?2:1,sessionOpen=scene==='trial',trialDone=false,words='',answer='constats',citation='parcours',proposition='',reason='',dataset='Avec une demande',draftPrompt='',notice='',selected='demo-result',sheet=false,dossierRead=false;
const detail=document.getElementById('d-demo-result'), root=document.getElementById('inbox');
document.addEventListener('submit',e=>e.preventDefault());
document.querySelectorAll('[data-action]').forEach(b=>{b.disabled=true;b.title='Commande réelle inactive dans le prototype';});
document.querySelectorAll('form button').forEach(b=>{b.type='button';b.disabled=true;});
const prototypeSource={base:'f65d23e',requests:'synthetic',commandsExecuted:0};
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function action(label,fn,primary=false,disabled=false){return `<button type="button" class="btn ${primary?'primary':''}" onclick="${fn}" ${disabled?'disabled':''}>${label}</button>`;}
function needHuman(){return !['returned','repairing','accepted','merging','merged','abandoned','outage','conflict','outdated'].includes(scene);}
function state(){return {prototype:true,variant,scene,screen,dossier:{version,read:dossierRead,current:!['outdated','conflict'].includes(scene)},session:{open:sessionOpen,dataset,trialDone},draft:{answer,words,citation,proposition,reason},answerRecorded:['returned','repairing','accepted','merging','merged','conflict','abandoned'].includes(scene),acceptanceValid:['accepted','merging','merged'].includes(scene),merged:scene==='merged',needsHuman:needHuman(),productionWrites:0,...prototypeSource};}
function sync(){const u=new URL(location.href);u.searchParams.set('variant',variant);u.searchParams.set('scene',scene);u.searchParams.set('view',screen);history.replaceState(null,'',u);document.getElementById('prototype-state').textContent=JSON.stringify(state(),null,2);}
function show(view){screen=view;if(view==='dossier')dossierRead=true;sheet=true;sync();render();}
function setScene(s){scene=s;screen=screens[s];selected='demo-result';sheet=true;sessionOpen=s==='trial';version=s==='new-result'?2:version;draftPrompt='';notice='';sync();render();}
function startTrial(){if(!editable())return;sessionOpen=true;screen='trial';sheet=true;notice='Le produit synthétique est ouvert. Aucune session réelle n’a été lancée.';sync();render();}
function chooseProposition(value){proposition=value;draftPrompt='' ;sync();render();}
function chooseDataset(value){dataset=value;sync();render();}
function finishTrial(){sessionOpen=false;trialDone=true;screen='findings';notice='Essai synthétique fermé. Tu peux préparer ton jugement.';sync();render();}
function editable(){return !['accepted','merging','merged','abandoned','outdated','conflict','returned','repairing','outage'].includes(scene);}
function status(){let text=needHuman()?'À toi de jouer · résultat prêt':scene==='merged'?'Terminé · fusion confirmée':scene==='accepted'?'Aucune action attendue · fusion en attente':scene==='abandoned'?'Terminé · aucune fusion':scene==='outdated'?'Dossier périmé · renouvellement attendu':scene==='conflict'?'Acceptation annulée · correction attendue':scene==='outage'?'Panne au lancement · réparation attendue':'L’usine travaille · aucune action attendue';return `<div class="chip ${needHuman()?'atoi':scene==='merged'?'ack':['outdated','conflict','outage'].includes(scene)?'bloque':''}">${text}</div>`;}
function heading(){return `<a class="btn ghost back" href="#inbox-list" onclick="returnToList();return false">← Retour à la liste</a>${status()}<div class="quoi">${titles[scene]}</div><p class="version">Usine · dossier ${version} du 11 octobre à ${version===1?'15:00':'16:10'} (Paris)</p>${notice?`<p class="notice" role="status">${esc(notice)}</p>`:''}`;}
function result(){return `<div class="sec"><span class="lbl">Pourquoi ça t’attend</span><p>Les vérifications du résultat sont terminées. Ton jugement porte sur ce que tu peux comprendre et faire dans le produit.</p></div><div class="sec"><span class="lbl">Ce qui a changé</span><p>Un résultat prêt à juger mène au dossier et à un essai de la bonne version. Après ta réponse, le chantier affiche la suite réelle.</p></div>${version===2?`<div class="callout good"><strong>Depuis ton dernier jugement</strong><p>« Je ne trouve pas où revoir mon constat. »</p><p>Le suivi conserve désormais ton texte et mène à sa preuve de correction.</p><button class="btn" onclick="show('dossier')">Voir la réponse à mes constats</button></div>`:''}<div class="facts"><div class="box"><b>Parcours vérifiés</b>4 parcours observés sur données synthétiques</div><div class="box"><b>Limites connues</b>Arrêt réel et notifications en mode Concentration non essayés</div></div><p><strong>À regarder pendant ton essai</strong></p><ul class="checklist"><li>Sais-tu pourquoi le résultat t’attend ?</li><li>Retrouves-tu le dossier et le produit à essayer ?</li><li>Après ton jugement, comprends-tu la suite ?</li></ul><div class="button-row">${action('Lire le dossier',"show('dossier')")}${action('Préparer mon essai','startTrial()',true)}${action('Préparer mon jugement',"show('findings')")}</div><p class="hint">Accepter ne fusionne rien immédiatement. Aucune réponse n’est donnée à ta place.</p>`;}
function dossier(){let unavailable=['outdated','conflict'].includes(scene);return `${unavailable?'<div class="callout warn"><strong>Ce dossier est périmé.</strong><p>Une nouvelle version est en préparation. L’essai et le jugement de ce dossier sont indisponibles.</p></div>':''}<p class="hint">Dossier synthétique présenté comme une source consultable. Les contenus ci-dessous sont des exemples de preuves, pas les preuves d’une livraison réelle.</p>${version===2?`<section class="box"><h3>0 · Depuis ton dernier jugement</h3><p><strong>Ton constat :</strong> « Je ne trouve pas où revoir mon constat. »</p><p>Réparation terminée : ton texte reste dans le suivi. Le parcours a été rejoué avec la correction.</p><button class="btn" onclick="proof('Parcours corrigé : consulter son constat depuis le suivi')">Voir la preuve</button></section>`:''}<h3>1 · Le résultat à juger</h3><p>Parcours d’acceptation du cockpit, dossier ${version}. La version essayée et celle jugée doivent être la même.</p><h3>2 · Résultats et propositions</h3><p>Quatre parcours observés : attente, consultation, essai et suivi.</p><div class="proposition"><strong>Proposition : ajouter un filtre dans l’historique</strong><p class="hint">Ce besoin dépasse la livraison. Ton verdict doit être explicite avant l’acceptation.</p><label>Ton choix <select id="proposal-verdict" onchange="chooseProposition(this.value)" ${!editable()?'disabled':''}><option value="">Choisir</option><option value="before" ${proposition==='before'?'selected':''}>À faire avant d’accepter</option><option value="plus_tard" ${proposition==='plus_tard'?'selected':''}>Plus tard</option><option value="sans_suite" ${proposition==='sans_suite'?'selected':''}>Sans suite</option></select></label><p class="draft">Choix en brouillon ; aucun verdict enregistré.</p></div><h3>Preuves consultables</h3><div class="button-row">${action('Parcours observés',"proof('Observation : dossier, essai, constats et fusion')")}${action('Tests et relecture',"proof('Tests verts et relecture : exemple synthétique')")}${action('Comparaison avec le prototype',"proof('Comparaison : mêmes ancres dans le détail de la demande')")}</div><details open><summary>Ce qui n’a PAS été vérifié</summary><ul class="checklist"><li>Arrêt propre pendant une livraison réelle.</li><li>Notification prioritaire en mode Concentration.</li><li>La santé du code, l’architecture, les dépendances et les secrets n’ont pas de contrôle dédié dans ce dossier exemple.</li></ul></details><details><summary>Référence de la version et pièces du dossier</summary><p>Dossier ${version} · commit synthétique ${version===1?'1111111':'2222222'} · empreinte synthétique dossier-${version}.</p><p class="empty-proof">Les sections complètes du vrai dossier restent dans sa page de preuves. Ce prototype en montre un extrait pour explorer la navigation.</p></details><div class="button-row">${action('Ouvrir la version à essayer','startTrial()',true,unavailable)}${action('Revenir au résultat',"show('result')")}</div>`;}
function proof(title){let d=document.getElementById('proof-dialog');if(!d){d=document.createElement('dialog');d.id='proof-dialog';d.style.cssText='max-width:640px;width:90vw;background:var(--surface);color:var(--ink);border:1px solid var(--line);border-radius:10px;padding:24px';document.body.appendChild(d);}d.innerHTML=`<h2>Pièce synthétique</h2><h3>${esc(title)}</h3><p style="margin:15px 0">Version : dossier ${version}. Observation exemple : l’utilisateur ouvre le résultat, lit le dossier, essaie le produit et retrouve sa réponse dans le suivi.</p><p style="margin:15px 0">Résultat de cet exemple : parcours observé. Cette pièce ne prouve aucune livraison réelle.</p><button class="btn" onclick="document.getElementById('proof-dialog').close()">Fermer la pièce</button>`;d.showModal();notice='Pièce synthétique consultée : '+title+'.';sync();}
function trial(){if(scene==='outage')return `<div class="callout warn"><strong>Le produit ne démarre pas.</strong><p>Le lancement a échoué. L’usine prépare une réparation ; ce n’est pas un jugement sur le résultat.</p></div><p>Aucun produit d’essai n’est resté ouvert. Ton acceptation n’a pas été enregistrée.</p><div class="button-row">${action('Voir le suivi',"show('follow')",true)}${action('Lire le dossier',"show('dossier')")}</div>`;if(['outdated','conflict'].includes(scene))return `<div class="callout warn">Le dossier est périmé. Aucun essai de cette version ne peut être ouvert.</div>${action('Voir le suivi',"show('follow')",true)}`;return `<p>Tu essaies <strong>la version du dossier ${version}</strong>, dans un environnement séparé. Les deux jeux de données sont synthétiques.</p><div class="button-row">${action(sessionOpen?'Produit ouvert dans cet aperçu':'Ouvrir le produit','startTrial()',true)}${sessionOpen?action('Fermer l’essai et préparer mon jugement','finishTrial()'):''}</div>${sessionOpen?`<label>Jeu de données <select id="dataset" onchange="chooseDataset(this.value)"><option ${dataset==='Avec une demande'?'selected':''}>Avec une demande</option><option ${dataset==='Aucune demande'?'selected':''}>Aucune demande</option></select></label><div class="mini-product"><div class="label">PRODUIT D’ESSAI SYNTHÉTIQUE · DOSSIER ${version}</div><h3>Ce qui t’attend</h3>${dataset==='Aucune demande'?'<p>Rien ne t’attend — vérifié à 15:00 (Paris).</p>':'<p><strong>Une livraison attend ton choix</strong></p><p>Pourquoi toi : tu dois choisir entre deux comportements visibles.</p><p>Option A : garder le comportement actuel. Option B : préparer un nouveau prototype.</p><div class="button-row">'+action('Essayer l’option A',"notice='Simulation : option A choisie dans le produit d’essai.';sync();render()")+action('Essayer l’option B',"notice='Simulation : option B choisie dans le produit d’essai.';sync();render()")+'</div>'}</div><p class="hint">Dans le vrai parcours, le produit s’ouvre à son adresse d’essai. L’agent peut t’aider à naviguer ; le dossier reste à lire par toi.</p>`:'<div class="callout">Aucun essai ouvert. Le lancement reprendra la version du dossier.</div>'}<div class="button-row">${action('Noter un constat',"show('findings')")}${action('Lire le dossier',"show('dossier')")}</div>`;}
function findings(){if(!editable())return `<p>La réponse de cette version est déjà enregistrée, ou son dossier n’est plus à jour.</p><div class="button-row">${action('Voir la suite réelle',"show('follow')",true)}</div><p class="hint">Le texte historique reste dans le suivi. Il n’est pas écrasé par une nouvelle réponse.</p>`;return `<p>Tes mots sont gardés tels quels. Cette zone prépare un passage vers ta session d’agent ; elle n’accepte rien par un clic.</p>${!trialDone?'<p class="hint">L’essai n’a pas été terminé dans ce prototype. Tu peux revenir essayer le produit avant de juger.</p>':''}<label for="finding-text"><strong>Ton constat ou tes mots de jugement</strong></label><textarea id="finding-text" placeholder="Ex. Je ne trouve pas où revoir mon constat." oninput="words=this.value;draftPrompt='';sync();updatePrepare()">${esc(words)}</textarea><p class="draft">Brouillon local · pas transmis · perdu si tu recharges le prototype</p><label>Concerne <select id="citation" onchange="citation=this.value;sync()"><option value="parcours" ${citation==='parcours'?'selected':''}>Un parcours attendu par la Spec</option><option value="new_need" ${citation==='new_need'?'selected':''}>Un besoin supplémentaire</option><option value="later" ${citation==='later'?'selected':''}>Une idée pour plus tard</option></select></label><details><summary>Comment le constat sera traité</summary><p>L’agent prépare la référence et la réparation quand elles existent. Le code classe le constat : réparation d’une exigence, clarification du périmètre, ou proposition pour plus tard.</p><p>Ce classement ne t’oblige pas à diagnostiquer le code ni à inventer un ticket.</p></details><h3>Le jugement à préparer</h3><div class="box">${[['constats','Constats rendus — corriger ou clarifier avant de juger à nouveau'],['accepté','Accepté — autoriser la fusion de cette version'],['abandonné','Abandonné — terminer sans fusionner']].map(([key,label])=>`<p><label><input type="radio" name="answer" value="${key}" ${answer===key?'checked':''} onchange="answer=this.value;draftPrompt='';sync();render()"> ${label}</label></p>`).join('')}</div>${answer==='abandonné'?`<label>Raison de l’abandon<input type="text" id="abandon-reason" value="${esc(reason)}" oninput="reason=this.value;sync();updatePrepare()"></label>`:''}${answer==='accepté'&&proposition==='before'?'<div class="callout warn">La proposition choisie « à faire avant d’accepter » bloque l’acceptation. Rends d’abord tes constats.</div>':''}${!proposition?'<div class="callout warn">La proposition du dossier attend encore ton verdict.</div>':''}<div class="button-row"><button class="btn primary" id="prepare-answer" onclick="prepare()" ${canPrepare()?'':'disabled'}>Préparer le prompt de ma session</button>${action('Revenir à l’essai','startTrial()')}</div><p class="hint">Continuer avec un agent consomme des tokens. L’agent enregistre la réponse par la commande du flux, avec tes mots, la version et l’empreinte du dossier.</p>${draftPrompt?`<label for="prepared-prompt"><strong>Prompt à copier</strong></label><textarea readonly class="prompt" id="prepared-prompt">${esc(draftPrompt)}</textarea><div class="button-row">${action('Copier le prompt','copyPrompt()',true)}</div><p class="draft">Copier n’envoie rien et ne démarre aucun agent.</p>`:''}`;}
function canPrepare(){return editable()&&words.trim().length>0&&Boolean(proposition)&&(answer!=='abandonné'||reason.trim().length>0)&&(answer!=='accepté'||proposition!=='before');}
function updatePrepare(){const b=document.getElementById('prepare-answer');if(b)b.disabled=!canPrepare();}
function prepare(){if(!canPrepare())return;draftPrompt=`Reprendre la session d’essai du résultat Cockpit synthétique.\nDossier ${version}, commit synthétique ${version===1?'1111111':'2222222'}, empreinte dossier-${version}.\nMa réponse préparée : ${answer}.\nMes mots exacts : ${words}\n${reason?'Raison : '+reason+'\n':''}Mon verdict sur la proposition : ${proposition}.\nContexte du constat : ${citation}.\nLire le dossier lié et vérifier qu’il est à jour. Ne pas résumer le dossier ni reformuler mes mots. Préparer les références et la réparation requises si le constat cite une exigence. Enregistrer uniquement ma réponse explicite par owner-answer, avec le commit et l’empreinte exacts du vrai dossier. Ne pas fusionner par un autre chemin.\nATTENTION : ces identifiants sont synthétiques ; ce prompt appartient au prototype et ne doit pas être exécuté.`;notice='Prompt préparé. La réponse n’est pas encore enregistrée.';sync();render();}
async function copyPrompt(){if(!draftPrompt)return;try{await navigator.clipboard.writeText(draftPrompt);notice='Prompt copié. Aucune réponse enregistrée.';}catch(e){notice='Sélectionne le texte du prompt pour le copier.';}sync();render();}
function follow(){let received=words||'Je ne trouve pas où revoir mon constat.';let states={returned:['Tes constats sont enregistrés','Aucune fusion. Le code prépare leur suite.'],repairing:['La correction est en cours','Une réparation est en cours ; un nouveau dossier sera préparé.'],accepted:['Ton acceptation est enregistrée','La version jugée n’est pas encore fusionnée.'],merging:['L’usine prépare la fusion','Elle vérifie que la branche de référence n’invalide pas le résultat accepté.'],merged:['La fusion est confirmée','Le résultat accepté est entré dans la version de référence.'],conflict:['Ton acceptation a été annulée','La reprise de la branche de référence a échoué. Aucune fusion ; correction et nouveau dossier attendus.'],abandoned:['Le chantier est abandonné','Le travail reste sur sa branche comme source. Rien n’a été fusionné.'],outdated:['Le dossier doit être renouvelé','Le résultat a changé depuis le dossier. Aucun jugement sur cette ancienne version.'],outage:['L’essai ne démarre pas','Une réparation du lancement est attendue. Aucun jugement inventé.']};let s=states[scene]||['Le résultat attend ton jugement','Lis le dossier et essaie le produit.'];return `<div class="callout ${scene==='merged'?'good':['conflict','outdated','outage'].includes(scene)?'warn':''}"><strong>${s[0]}</strong><p>${s[1]}</p></div>${['returned','repairing','new-result'].includes(scene)?`<h3>Tes mots et leur suite</h3><div class="box"><strong>« ${esc(received)} »</strong><p>${citation==='new_need'?'Le besoin dépasse le périmètre : clarification de la Spec attendue.':citation==='later'?'Proposition créée pour plus tard. Elle ne bloque pas la livraison.':scene==='repairing'?'Une réparation du parcours attendu est en cours.':'Une réparation du parcours attendu est à préparer.'}</p><p class="hint">Référence et classement établis par le flux ; texte de ton constat conservé.</p></div>`:''}<h3>Historique du résultat</h3>${historyRows().map(([t,b])=>`<div class="line"><strong>${t}</strong><p class="hint">${b}</p></div>`).join('')}<details><summary>Version jugée, version fusionnée et dossier</summary><p>Dossier ${version} · résultat jugé : ${version===1?'1111111':'2222222'} (synthétique).</p><p>Version fusionnée : ${scene==='merged'?'3333333 (synthétique)':'aucune preuve de fusion'}.</p><p>Le dossier jugé reste inchangé. La preuve de fusion est séparée.</p></details><div class="button-row">${action('Consulter le dossier',"show('dossier')")}${scene==='merged'?action('Voir la preuve de fusion',"proof('fusion.html : résultat jugé et commit effectivement fusionné')") :''}${needHuman()?action('Préparer mon jugement',"show('findings')",true):''}</div><p class="hint">Le suivi reste accessible depuis Projets quand la demande quitte la boîte de réception.</p>`;}
function historyRows(){let rows=[['15:00 · Résultat prêt','Dossier et version d’essai disponibles.']];if(['returned','repairing'].includes(scene))rows.push(['15:18 · Constats rendus','Tes mots sont liés au dossier jugé.'],[scene==='repairing'?'15:22 · Correction en cours':'15:19 · Suite préparée','Aucune fusion avant un nouveau jugement.']);if(['accepted','merging','merged','conflict'].includes(scene))rows.push(['15:18 · Accepté','Acceptation liée à la version du dossier.']);if(scene==='merging')rows.push(['15:19 · Fusion en cours','Vérifications de reprise en cours.']);if(scene==='merged')rows.push(['15:20 · Fusion confirmée','Une preuve identifie le résultat jugé et la version fusionnée.']);if(scene==='conflict')rows.push(['15:19 · Acceptation annulée','Conflit à la reprise de la branche de référence. Correction puis nouveau dossier.']);if(scene==='abandoned')rows.push(['15:18 · Abandonné','Raison : '+(reason||'Le besoin n’est plus prioritaire.')]);if(scene==='outage')rows.push(['15:08 · Essai impossible','Le produit n’a pas démarré.']);if(scene==='outdated')rows.push(['15:08 · Dossier périmé','Le résultat a changé.']);return rows;}
const content={result,dossier,trial,findings,follow};
function VariantA(){return `<nav class="tabs" aria-label="Parcours du résultat">${Object.keys(labels).map(k=>`<button aria-selected="${screen===k}" onclick="show('${k}')">${labels[k]}</button>`).join('')}</nav>${content[screen]()}`;}
function VariantB(){const order=['result','dossier','trial','findings','follow'];return `<div class="two-columns"><nav class="rail" aria-label="Étapes du parcours">${order.map((k,i)=>`<button aria-current="${screen===k}" onclick="show('${k}')">${i+1} · ${labels[k]}</button>`).join('')}</nav><section><span class="step-count">Étape ${order.indexOf(screen)+1} sur 5</span><h3>${labels[screen]}</h3>${content[screen]()}${order.indexOf(screen)<4?`<div class="button-row">${action('Étape suivante →',`show('${order[order.indexOf(screen)+1]}')`)}</div>`:''}</section></div>`;}
function VariantC(){return `<p class="hint">Un seul détail à parcourir : le résultat, son dossier, puis le journal de tes actions.</p><details ${screen==='result'?'open':''} ontoggle="if(this.open){screen='result';sync()}"><summary>Le résultat et ce qui t’attend</summary>${result()}</details><details ${screen==='dossier'?'open':''} ontoggle="if(this.open){screen='dossier';sync()}"><summary>Le dossier · preuves et limites</summary>${dossier()}</details><details ${screen==='trial'?'open':''} ontoggle="if(this.open){screen='trial';sync()}"><summary>Essayer la version du dossier</summary>${trial()}</details><details ${screen==='findings'?'open':''} ontoggle="if(this.open){screen='findings';sync()}"><summary>Préparer mon jugement et mes constats</summary>${findings()}</details><details ${screen==='follow'?'open':''} ontoggle="if(this.open){screen='follow';sync()}"><summary>Suivi · constats, acceptation, fusion</summary>${follow()}</details>`;}
function returnToList(){sheet=false;root.classList.remove('sheet');sync();}
function render(){detail.innerHTML=`<div class="journey">${heading()}${{A:VariantA,B:VariantB,C:VariantC}[variant]()}</div>`;root.querySelectorAll('.detail').forEach(d=>d.classList.toggle('on',d.id==='d-'+selected));root.querySelectorAll('.li').forEach(l=>l.setAttribute('aria-current',l.dataset.id===selected?'true':'false'));root.classList.toggle('sheet',sheet);let row=root.querySelector('[data-id="demo-result"]');row.hidden=!needHuman();row.querySelector('.q').textContent=scene==='new-result'?'Un nouveau résultat attend ton jugement':'Le cockpit attend ton jugement';document.querySelector('#inbox-list h2 .mono').textContent=needHuman()?'2':'1';document.getElementById('variant-name').textContent=variant+' · '+names[variant];document.getElementById('scenario').value=scene;document.querySelector('#ch-demo-result .cockpit-chantier-s').textContent=titles[scene];let track=document.querySelector('#ch-demo-result .cockpit-stepper');let phase=['accepted','merging'].includes(scene)?5:scene==='merged'?6:['returned','repairing','outage'].includes(scene)?3:4;track.innerHTML=['Cadrage','Spec','Graphe','Livraison','À juger','Accepté','Fusionné'].map((t,i)=>'<span class="'+(i<phase?'done':i===phase?'cur':'')+'" title="'+t+'"></span>').join('');track.setAttribute('aria-label',titles[scene]);let b=document.getElementById('simulate-answer');b.disabled=!draftPrompt||!canPrepare();sync();}
root.addEventListener('click',e=>{const r=e.target.closest('.li');if(r){e.preventDefault();selected=r.dataset.id;sheet=true;render();if(matchMedia('(max-width:930px)').matches)root.scrollIntoView({block:'start'});}if(e.target.closest('.back')){e.preventDefault();returnToList();}});
document.querySelectorAll('.cockpit-projects a').forEach(a=>{a.href='#d-demo-result';a.onclick=e=>{e.preventDefault();selected='demo-result';screen='follow';sheet=true;render();detail.scrollIntoView({block:'start'});};});
document.querySelector('.cockpit-projects .zone-body').insertAdjacentHTML('beforeend','<div class="button-row" style="margin-top:12px"><button class="btn" id="project-follow">Suivre le résultat du cockpit →</button><span id="journey-status" class="muted"></span></div>');
document.getElementById('project-follow').onclick=()=>{selected='demo-result';sheet=true;screen='follow';render();detail.scrollIntoView({block:'start'});};
document.querySelector('.prototype-tools').insertAdjacentHTML('beforeend','<div style="margin-top:8px"><button class="btn" id="simulate-answer" disabled>Simuler l’enregistrement de ma réponse préparée</button><span style="margin-left:8px">Outil du prototype uniquement</span></div>');
document.getElementById('simulate-answer').onclick=()=>{if(!canPrepare()||!draftPrompt)return;setScene(answer==='accepté'?'accepted':answer==='abandonné'?'abandoned':'returned');};
function cycle(n){variant=variants[(variants.indexOf(variant)+n+3)%3];sync();render();}
document.getElementById('previous-variant').onclick=()=>cycle(-1);document.getElementById('next-variant').onclick=()=>cycle(1);
document.getElementById('scenario').onchange=e=>setScene(e.target.value);
document.getElementById('reset').onclick=()=>{version=1;words='';answer='constats';citation='parcours';proposition='';reason='';trialDone=false;dossierRead=false;setScene('ready');sheet=false;render();};
document.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select,[contenteditable]'))return;if(e.key==='ArrowLeft')cycle(-1);if(e.key==='ArrowRight')cycle(1);});
if(qp.has('view')||scene!=='ready')sheet=true;
render();

